Using Prometheus-style metrics (the de facto standard for
container-based production systems, directly compatible with
Module 32's Kubernetes infrastructure):

import { Counter, Histogram, Gauge } from 'prom-client';

// TRAFFIC: how many requests per second
const requestCounter = new Counter({
  name: 'http_requests_total',
  help: 'Total HTTP requests',
  labelNames: ['method', 'route', 'status_code']
});

// LATENCY: how long requests take (p50, p95, p99 percentiles)
const requestDuration = new Histogram({
  name: 'http_request_duration_seconds',
  help: 'HTTP request duration in seconds',
  labelNames: ['method', 'route'],
  buckets: [0.01, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5] // seconds
});

// ERRORS: fraction of requests returning errors
// Derived from requestCounter: rate(errors) / rate(total)

// SATURATION: how full is the job queue (Module 28's queue)
const queueDepth = new Gauge({
  name: 'job_queue_depth',
  help: 'Current number of jobs waiting in queue',
  labelNames: ['queue_name']
});

// Middleware that instruments EVERY request automatically
app.use((req, res, next) => {
  const end = requestDuration.startTimer({ method: req.method, route: req.path });
  res.on('finish', () => {
    requestCounter.inc({ method: req.method, route: req.path, status_code: res.statusCode });
    end(); // records latency automatically
  });
  next();
});

