// PROMETHEUS ALERT RULES - these run against the metrics this
// lesson's instrumentation records

// GOOD ALERT: high error rate, sustained, on a specific endpoint
// Error rate > 1% for checkout specifically, for 5 continuous minutes
groups:
  - name: checkout_alerts
    rules:
      - alert: CheckoutErrorRateHigh
        expr: |
          rate(http_requests_total{route='/checkout', status_code=~'5..'}[5m])
          /
          rate(http_requests_total{route='/checkout'}[5m])
          > 0.01
        for: 5m  # sustained, not a single spike
        labels:
          severity: critical
        annotations:
          summary: "Checkout error rate above 1% for 5 minutes"

// THE THREE PROPERTIES OF A GOOD ALERT:
// 1. ACTIONABLE: someone woken up at 3am can actually DO something
//    about it immediately
// 2. SYMPTOM-BASED: alert on what USERS experience (error rate,
//    latency), not on internal causes (CPU usage, memory)
// 3. SUSTAINED: use 'for: 5m' to require the condition to persist,
//    preventing single-spike false alarms

// POOR ALERT: CPU > 70% for 2 minutes
// NOT actionable: a responder cannot directly lower CPU
// NOT symptom-based: high CPU doesn't mean users are affected
// NOT well-calibrated: routine load spikes trigger this constantly

