OpenTelemetry is the vendor-neutral, industry-standard tracing library,
directly compatible with Module 32's Kubernetes and any cloud provider:

import { trace, context, propagation } from '@opentelemetry/api';

const tracer = trace.getTracer('order-service');

// ORDER SERVICE: generate the root span for an incoming request
app.post('/checkout', async (req, res) => {
  const span = tracer.startSpan('checkout.process', {
    attributes: {
      'user.id': req.userId,
      'order.item_count': req.body.items.length
    }
  });

  const ctx = trace.setSpan(context.active(), span);

  try {
    // Propagate trace context to downstream service calls
    const headers = {};
    propagation.inject(ctx, headers); // injects traceparent header

    const inventoryOk = await fetch('http://inventory-service/check', {
      headers // downstream service extracts this to link spans
    });

    if (!inventoryOk.ok) {
      span.setStatus({ code: SpanStatusCode.ERROR, message: 'Inventory check failed' });
      span.recordException(new Error('Inventory unavailable'));
    }

    res.json({ success: true });
    span.setStatus({ code: SpanStatusCode.OK });
  } catch (err) {
    span.recordException(err as Error);
    span.setStatus({ code: SpanStatusCode.ERROR });
    throw err;
  } finally {
    span.end(); // ALWAYS end the span, even on error
  }
});

