// a child span that links to the calling service's trace
import { trace, context, propagation, SpanStatusCode } from '@opentelemetry/api';

const inventoryTracer = trace.getTracer('inventory-service');

app.get('/check', async (req, res) => {
  // Extract the trace context propagated from the Order Service
  const incomingCtx = propagation.extract(context.active(), req.headers);

  // Create a child span that LINKS to the calling service's span
  const span = inventoryTracer.startSpan(
    'inventory.check',
    { attributes: { 'product.ids': req.query.productIds } },
    incomingCtx // parent context from the upstream service
  );

  try {
    const available = await checkInventoryDatabase(req.query.productIds);
    span.setAttribute('inventory.all_available', available);
    res.json({ available });
    span.setStatus({ code: SpanStatusCode.OK });
  } catch (err) {
    span.recordException(err as Error);
    span.setStatus({ code: SpanStatusCode.ERROR });
    res.status(500).json({ error: 'Inventory check failed' });
  } finally {
    span.end();
  }
});

