Using pino (the de facto standard structured logger for Node.js,
producing JSON output by default):

import pino from 'pino';

const logger = pino({
  level: process.env.LOG_LEVEL ?? 'info',
  // In production, formatters serialize to JSON automatically
  // In development, use pino-pretty for readable output
  transport: process.env.NODE_ENV !== 'production'
    ? { target: 'pino-pretty' }
    : undefined
});

// Middleware: create a per-request child logger with trace context
app.use((req, res, next) => {
  const span = trace.getActiveSpan();
  const traceId = span?.spanContext().traceId ?? 'no-trace';
  const spanId = span?.spanContext().spanId ?? 'no-span';

  // req.log is available to all route handlers for this request
  req.log = logger.child({
    traceId,     // correlates logs with traces (lesson 3)
    spanId,
    requestId: req.headers['x-request-id'] ?? crypto.randomUUID(),
    userId: req.userId,
    service: 'order-service'
  });
  next();
});

// Route handler: logging with appropriate levels
app.post('/orders', async (req, res) => {
  req.log.info({ body: req.body }, 'Order creation started');

  try {
    const order = await createOrder(req.body);
    req.log.info({ orderId: order._id }, 'Order created successfully');
    res.json({ order });
  } catch (err) {
    req.log.error({ err, body: req.body }, 'Order creation failed');
    res.status(500).json({ error: 'Order creation failed' });
  }
});

