A complete SLI/SLO definition for a checkout service,
directly built from lesson 2's metrics instrumentation:

// SERVICE LEVEL INDICATOR (SLI):
// The fraction of /checkout requests that succeed (2xx response)
// and complete within 500ms, measured over a rolling 30-day window
//
// PromQL expression:
// sum(rate(http_requests_total{route='/checkout', status_code=~'2..'}[30d]))
// /
// sum(rate(http_requests_total{route='/checkout'}[30d]))
// [where 'succeed within 500ms' is encoded in the latency histogram]

// SERVICE LEVEL OBJECTIVE (SLO):
// The /checkout SLI must be >= 99.5% over any rolling 30-day window

// ERROR BUDGET:
// Total requests in 30 days: ~1,000,000
// Allowed failures (100% - 99.5% = 0.5%): 5,000 requests
// Current consumed budget: 1,200 failures
// Remaining budget: 3,800 failures (76% remaining)
//
// THE ERROR BUDGET IS NOT A SCORE TO MINIMIZE -
// it's a TRADEOFF CURRENCY:
// - Remaining budget is AVAILABLE to spend on risky deploys
// - Exhausted budget means FREEZE on risky changes until it
//   refills (which it does naturally as the 30-day window
//   rolls forward and old failures drop off)

sections.code:
// SLO DASHBOARD CALCULATION
// (typically done in a monitoring tool like Grafana, but shown
// here as code to make the math explicit)

async function calculateSLOStatus(windowDays: number = 30) {
  const windowMs = windowDays * 24 * 60 * 60 * 1000;
  const windowStart = new Date(Date.now() - windowMs);

  // From lesson 2's metrics database (Prometheus/VictoriaMetrics)
  const totalRequests = await metrics.query(
    `sum(increase(http_requests_total{route='/checkout'}[${windowDays}d]))`
  );

  const goodRequests = await metrics.query(
    `sum(increase(http_requests_total{route='/checkout', status_code=~'2..'}[${windowDays}d]))`
  );

  const sli = goodRequests / totalRequests; // e.g. 0.9975 = 99.75%
  const slo = 0.995;                         // our commitment: 99.5%
  const errorBudget = totalRequests * (1 - slo); // allowed failures
  const consumedBudget = totalRequests - goodRequests; // actual failures
  const remainingBudget = errorBudget - consumedBudget;
  const budgetRemainingPct = remainingBudget / errorBudget;

  return {
    sli: `${(sli * 100).toFixed(3)}%`,
    sloTarget: `${(slo * 100).toFixed(1)}%`,
    isMeetingSLO: sli >= slo,
    errorBudgetTotal: Math.round(errorBudget),
    errorBudgetConsumed: Math.round(consumedBudget),
    errorBudgetRemainingPct: `${(budgetRemainingPct * 100).toFixed(1)}%`,
    deploymentRisk: budgetRemainingPct > 0.5 ? 'low' : budgetRemainingPct > 0.2 ? 'medium' : 'high'
  };
}

